<?php
class MediaController extends AdminController
{
 public function index(){ $this->guardAdmin();$db=new Database();$media=$db->fetchAll('SELECT m.*,u.username FROM media m LEFT JOIN users u ON u.id=m.user_id ORDER BY m.created_at DESC');$this->view('admin/media/index',array('media'=>$media)); }
 public function upload(){ $this->postGuard();if(empty($_FILES['file'])||$_FILES['file']['error']!==UPLOAD_ERR_OK)return $this->redirect('admin/media');$file=$_FILES['file'];$allowed=array('image/jpeg'=>'jpg','image/png'=>'png','image/gif'=>'gif','image/webp'=>'webp','application/pdf'=>'pdf');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!isset($allowed[$mime])||$file['size']>5*1024*1024)return $this->redirect('admin/media');$name=bin2hex(random_bytes(12)).'.'.$allowed[$mime];$dir=__DIR__.'/../../uploads/media/'.date('Y/m');if(!is_dir($dir))mkdir($dir,0755,true);$path=$dir.'/'.$name;if(!move_uploaded_file($file['tmp_name'],$path))return $this->redirect('admin/media');$relative='uploads/media/'.date('Y/m').'/'.$name;$db=new Database();$db->query('INSERT INTO media (user_id,folder,original_name,file_name,file_path,mime_type,file_size) VALUES (:user_id,:folder,:original_name,:file_name,:file_path,:mime_type,:file_size)',array(':user_id'=>Auth::user()['id'],':folder'=>'media',':original_name'=>$file['name'],':file_name'=>$name,':file_path'=>$relative,':mime_type'=>$mime,':file_size'=>(int)$file['size']));$id=$db->lastInsertId();$this->audit('upload','media',$id,null,array('path'=>$relative));return $this->redirect('admin/media');}
 public function delete($id){$this->postGuard();$db=new Database();$row=$db->fetch('SELECT * FROM media WHERE id=:id',array(':id'=>(int)$id));if($row){$full=__DIR__.'/../../'.$row['file_path'];if(is_file($full))unlink($full);$db->query('DELETE FROM media WHERE id=:id',array(':id'=>(int)$id));$this->audit('delete','media',$id,$row);}return $this->redirect('admin/media');}
}
